```swift
// Fetch
let request = Task.fetchRequest()
request.predicate = NSPredicate(format: "isComplete == NO")
request.sortDescriptors = [NSSortDescriptor(key: "dueDate", ascending: true)]
let tasks = try context.fetch(request)

// Mutate and save
let newTask = Task(context: context)
newTask.title = "Ship the release"
newTask.isComplete = false
try context.save()   // nothing hits disk until this call
```

A predicate filters at the **store** level (translated to SQL under the hood for the default SQLite store), not by fetching everything and filtering in Swift — this is the difference between a query that scales and one that silently loads an entire table into memory as the data grows.

```swift
@Model
class Task {
    var title: String
    var isComplete: Bool = false
    var dueDate: Date?
}

// In a SwiftUI view:
@Query(filter: #Predicate<Task> { !$0.isComplete },
       sort: \Task.dueDate)
var tasks: [Task]

@Environment(\.modelContext) var context
func addTask() {
    context.insert(Task(title: "Ship the release"))
    // SwiftData autosaves by default; explicit try context.save() still available
}
```

`@Model` replaces the `.xcdatamodeld` visual editor entirely — the entity is just a plain Swift class with property wrappers doing the work, and `#Predicate` gives compile-time-checked, type-safe queries instead of Core Data's string-based `NSPredicate` format strings, which fail silently at runtime on a typo.
